920		easeFactor: number,
921		lapseCount: number,
922		repetitions: number,
923	): ScriptPropertyCard {
924		return ScriptPropertyCard.fromDTO({
925			id: `${character}-recognition`,
926			question: "question",
927			correctAnswer: "answer",
928			choices: ["answer"],
929			srs: {
930				easeFactor,
931				interval: 10,
932				repetitions,
933				learningStep: null,
934				nextReviewDate: "2026-01-01T00:00:00.000Z",
935				lastReviewDate: "2026-01-01T00:00:00.000Z",
936				lapseCount,
937			},
938			symbolCharacter: character,
939			property: "recognition",
