	};
}

describe("toneSyllablesOf", () => {
	it("AC7: keeps only syllables with a non-null, non-empty tone, mapped to {text, tone}", () => {
		const entry = vocabEntry([
			syllable("แมว", "rising"),
			syllable("no-tone", null),
			syllable("empty-tone", ""),
		]);

